package businessflow

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"
)

type acceptanceConfig struct {
	WorkspaceID string `json:"workspace_id"`
	Identities  map[string]struct {
		Password string `json:"password"`
	} `json:"identities"`
}

type runtimeClient struct {
	base, token string
	client      *http.Client
}

func loadRuntime(t *testing.T) (string, acceptanceConfig) {
	t.Helper()
	base := os.Getenv("CRM_RUNTIME_URL")
	if base == "" {
		t.Skip("CRM_RUNTIME_URL is required for managed-Runtime business flows")
	}
	raw, err := os.ReadFile("../../config/acceptance-credentials.json")
	if err != nil {
		t.Fatal(err)
	}
	var cfg acceptanceConfig
	if err := json.Unmarshal(raw, &cfg); err != nil {
		t.Fatal(err)
	}
	return strings.TrimRight(base, "/"), cfg
}

func login(t *testing.T, base string, cfg acceptanceConfig, user string) runtimeClient {
	t.Helper()
	payload := map[string]any{"workspace_id": cfg.WorkspaceID, "login": user, "password": cfg.Identities[user].Password}
	raw, _ := json.Marshal(payload)
	resp, err := http.Post(base+"/auth/login", "application/json", bytes.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("login %s: %d %s", user, resp.StatusCode, body)
	}
	var result map[string]any
	if err := json.Unmarshal(body, &result); err != nil {
		t.Fatal(err)
	}
	token, _ := result["access_token"].(string)
	if token == "" {
		t.Fatalf("login %s returned no access_token", user)
	}
	return runtimeClient{base: base, token: token, client: &http.Client{Timeout: 10 * time.Second}}
}

func (c runtimeClient) request(t *testing.T, method, endpoint, idempotency string, payload any, want ...int) any {
	t.Helper()
	var body io.Reader
	if payload != nil {
		raw, err := json.Marshal(payload)
		if err != nil {
			t.Fatal(err)
		}
		body = bytes.NewReader(raw)
	}
	req, err := http.NewRequestWithContext(t.Context(), method, c.base+endpoint, body)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Authorization", "Bearer "+c.token)
	req.Header.Set("X-Domainry-Product-Surface", "business_workspace")
	if payload != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if idempotency != "" {
		req.Header.Set("Idempotency-Key", idempotency)
	}
	resp, err := c.client.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	matched := false
	for _, status := range want {
		if resp.StatusCode == status {
			matched = true
		}
	}
	if !matched {
		t.Fatalf("%s %s: got %d want %v: %s", method, endpoint, resp.StatusCode, want, raw)
	}
	if len(raw) == 0 {
		return nil
	}
	var result any
	if err := json.Unmarshal(raw, &result); err != nil {
		t.Fatalf("decode %s: %v: %s", endpoint, err, raw)
	}
	return result
}

func objectMap(value any) map[string]any { result, _ := value.(map[string]any); return result }
func array(value any) []any              { result, _ := value.([]any); return result }
func data(record map[string]any) map[string]any {
	result, _ := record["data"].(map[string]any)
	return result
}
func recordID(record any) string { return objectMap(record)["id"].(string) }

func unique(prefix string) string { return fmt.Sprintf("%s-%d", prefix, time.Now().UnixNano()) }

func createLead(t *testing.T, client runtimeClient, key, company, amount string) map[string]any {
	result := client.request(t, http.MethodPost, "/objects/sales_lead/records", key,
		map[string]any{"data": map[string]any{"company_name": company, "contact_name": "验收联系人", "contact_phone": "13812345678", "expected_amount": amount, "source": "website"}}, http.StatusCreated, http.StatusOK)
	return objectMap(result)
}

func advance(t *testing.T, client runtimeClient, leadID, target, key string) {
	result := objectMap(client.request(t, http.MethodPost, "/objects/sales_lead/records/"+leadID+"/actions/sales_lead.advance_status", key,
		map[string]any{"data": map[string]any{"target_status": target, "changed_at": time.Now().UTC().Format(time.RFC3339Nano), "request_id": key}}, http.StatusOK))
	if objectMap(result["output"])["status"] != target {
		t.Fatalf("advance %s output: %#v", target, result)
	}
}

func listRecords(t *testing.T, client runtimeClient, object string) []any {
	result := objectMap(client.request(t, http.MethodGet, "/objects/"+object+"/records?page=1&page_size=100", "", nil, http.StatusOK))
	return array(result["items"])
}

func countRelation(items []any, field, id string) int {
	count := 0
	for _, item := range items {
		if data(objectMap(item))[field] == id {
			count++
		}
	}
	return count
}

