func UpdateOwned(ctx context.Context, caps capabilities.UpdateOwnedCapabilities, input capabilities.UpdateOwnedInput) (capabilities.UpdateOwnedOutput, error) {
	if caps.Execution == nil || caps.SalesLead == nil {
		return capabilities.UpdateOwnedOutput{}, businessError("crm.capability.unavailable")
	}
	lead, err := caps.SalesLead.GetForUpdate(ctx, caps.Execution.TargetID())
