		return capabilities.UpdateOwnedOutput{}, err
	}
	if err := requiredOwner(lead.OwnerUser, caps.Execution.Principal()); err != nil {
		return capabilities.UpdateOwnedOutput{}, err
	}
	if lead.Status == schema.SalesLeadStatus("converted") || lead.Status == schema.SalesLeadStatus("lost") {
		return capabilities.UpdateOwnedOutput{}, businessError("crm.lead.terminal")
	}
	mutation := data.NewSalesLeadUpdate(lead.ID).
		SetContactName(input.ContactName).
		SetContactPhone(input.ContactPhone).
		SetExpectedAmount(input.ExpectedAmount).
		SetSource(schema.SalesLeadSource(input.Source)).
		RequireStatusEqual(lead.Status, "crm.lead.concurrent_status_change").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	updated, err := caps.SalesLead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.UpdateOwnedOutput{}, err
	}
	return capabilities.UpdateOwnedOutput{LeadID: updated.ID, Status: string(updated.Status)}, nil
}
