func AdvanceStatus(ctx context.Context, caps capabilities.AdvanceStatusCapabilities, input capabilities.AdvanceStatusInput) (capabilities.AdvanceStatusOutput, error) {
	if caps.Execution == nil || caps.SalesLead == nil {
		return capabilities.AdvanceStatusOutput{}, businessError("crm.capability.unavailable")
	}
	lead, err := caps.SalesLead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.AdvanceStatusOutput{}, err
	}
	if err := requiredOwner(lead.OwnerUser, caps.Execution.Principal()); err != nil {
		return capabilities.AdvanceStatusOutput{}, err
	}
	target := schema.SalesLeadStatus(input.TargetStatus)
	valid := (lead.Status == schema.SalesLeadStatus("new") && target == schema.SalesLeadStatus("contacted")) ||
		(lead.Status == schema.SalesLeadStatus("contacted") && target == schema.SalesLeadStatus("qualified")) ||
		(lead.Status == schema.SalesLeadStatus("qualified") && target == schema.SalesLeadStatus("lost"))
	if !valid {
		return capabilities.AdvanceStatusOutput{}, businessError("crm.lead.invalid_transition")
	}
	mutation := data.NewSalesLeadUpdate(lead.ID).
		SetStatus(target).
		SetStatusChangedAt(input.ChangedAt).
		RequireStatusEqual(lead.Status, "crm.lead.concurrent_status_change").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	updated, err := caps.SalesLead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.AdvanceStatusOutput{}, err
	}
	return capabilities.AdvanceStatusOutput{LeadID: updated.ID, Status: string(updated.Status)}, nil
}
