func businessError(code string) error {
	return &capabilities.BusinessError{Code: code}
}

func amountAtLeast(value string, threshold string) (bool, error) {
	amount, ok := new(big.Rat).SetString(value)
	if !ok {
		return false, businessError("crm.amount.invalid")
	}
	limit, ok := new(big.Rat).SetString(threshold)
	if !ok {
		return false, businessError("crm.amount.threshold_invalid")
	}
	return amount.Cmp(limit) >= 0, nil
}

func requiredOwner(owner *string, principal capabilities.Principal) error {
	if owner == nil || *owner == "" || *owner != principal.UserID {
		return businessError("crm.lead.owner_required")
	}
	return nil
}

func nonBlank(value *string) bool {
	return value != nil && strings.TrimSpace(*value) != ""
}

