func objectMap(value any) map[string]any { result, _ := value.(map[string]any); return result }
func array(value any) []any              { result, _ := value.([]any); return result }
func data(record map[string]any) map[string]any {
	result, _ := record["data"].(map[string]any)
	return result
}
func recordID(record any) string { return objectMap(record)["id"].(string) }

func unique(prefix string) string { return fmt.Sprintf("%s-%d", prefix, time.Now().UnixNano()) }

func createLead(t *testing.T, client runtimeClient, key, company, amount string) map[string]any {
	result := client.request(t, http.MethodPost, "/objects/sales_lead/records", key,
		map[string]any{"data": map[string]any{"company_name": company, "contact_name": "验收联系人", "contact_phone": "13812345678", "expected_amount": amount, "source": "website"}}, http.StatusCreated, http.StatusOK)
	return objectMap(result)
}

func advance(t *testing.T, client runtimeClient, leadID, target, key string) {
	result := objectMap(client.request(t, http.MethodPost, "/objects/sales_lead/records/"+leadID+"/actions/sales_lead.advance_status", key,
		map[string]any{"data": map[string]any{"target_status": target, "changed_at": time.Now().UTC().Format(time.RFC3339Nano), "request_id": key}}, http.StatusOK))
	if objectMap(result["output"])["status"] != target {
		t.Fatalf("advance %s output: %#v", target, result)
	}
}

func listRecords(t *testing.T, client runtimeClient, object string) []any {
	result := objectMap(client.request(t, http.MethodGet, "/objects/"+object+"/records?page=1&page_size=100", "", nil, http.StatusOK))
	return array(result["items"])
}

func countRelation(items []any, field, id string) int {
	count := 0
	for _, item := range items {
		if data(objectMap(item))[field] == id {
			count++
		}
	}
	return count
}

// BF-03 / CRM-06..09,13: this is the highest-risk real-Runtime journey.
func TestBF03HighestRiskLargeApproval(t *testing.T) {
	base, cfg := loadRuntime(t)
	rep := login(t, base, cfg, "east_rep")
	director := login(t, base, cfg, "sales_director")
	key := unique("bf03")
	lead := createLead(t, rep, key+"-create", "BF03大额审批公司"+key, "150000.00")
	leadID := recordID(lead)
	advance(t, rep, leadID, "contacted", key+"-contacted")
	advance(t, rep, leadID, "qualified", key+"-qualified")
	requestResult := objectMap(rep.request(t, http.MethodPost, "/objects/sales_lead/records/"+leadID+"/actions/sales_lead.request_conversion", key+"-request",
		map[string]any{"data": map[string]any{"requested_at": time.Now().UTC().Format(time.RFC3339Nano), "request_id": key + "-request"}}, http.StatusOK))
	conversionID, _ := objectMap(requestResult["output"])["conversion_request_id"].(string)
	if conversionID == "" || objectMap(requestResult["record"])["id"] != leadID {
		t.Fatalf("pending approval missing identities: %#v", requestResult)
	}
	var processID, taskID string
	deadline := time.Now().Add(45 * time.Second)
	for time.Now().Before(deadline) && taskID == "" {
		processes := array(director.request(t, http.MethodGet, "/business/workflow/processes?page=1&page_size=100", "", nil, http.StatusOK))
		for _, value := range processes {
			process := objectMap(value)
			if process["record_id"] == conversionID {
				processID, _ = process["id"].(string)
			}
		}
		if processID != "" {
			tasks := array(director.request(t, http.MethodGet, "/business/workflow/tasks?page=1&page_size=100", "", nil, http.StatusOK))
			for _, value := range tasks {
				task := objectMap(value)
				if task["process_id"] == processID && task["status"] == "open" {
					taskID, _ = task["id"].(string)
				}
			}
		}
		if taskID == "" {
			time.Sleep(100 * time.Millisecond)
		}
	}
	if taskID == "" {
		t.Fatalf("approval task not materialized for %s", conversionID)
	}
	rep.request(t, http.MethodPost, "/business/workflow/tasks/"+taskID+"/approve", key+"-denied", map[string]any{"comment": "越权审批"}, http.StatusForbidden)
	director.request(t, http.MethodPost, "/business/workflow/tasks/"+taskID+"/approve", key+"-approve", map[string]any{"comment": "批准转化"}, http.StatusOK)
	leadAfter := objectMap(director.request(t, http.MethodGet, "/objects/sales_lead/records/"+leadID, "", nil, http.StatusOK))
	if data(leadAfter)["status"] != "converted" {
		t.Fatalf("lead not converted: %#v", leadAfter)
	}
	if got := countRelation(listRecords(t, director, "customer"), "lead_id", leadID); got != 1 {
		t.Fatalf("customer count=%d", got)
	}
	rep.request(t, http.MethodPost, "/objects/sales_lead/records/"+leadID+"/actions/sales_lead.request_conversion", key+"-replay",
		map[string]any{"data": map[string]any{"requested_at": time.Now().UTC().Format(time.RFC3339Nano), "request_id": key + "-replay"}}, http.StatusOK)
	if got := countRelation(listRecords(t, director, "customer"), "lead_id", leadID); got != 1 {
		t.Fatalf("replay customer count=%d", got)
	}
	notifications := objectMap(rep.request(t, http.MethodGet, "/business/notifications?page=1&page_size=100", "", nil, http.StatusOK))
	found := false
	for _, value := range array(notifications["items"]) {
		item := objectMap(value)
		if item["event_type"] == "conversion.approved" && item["subject_id"] == leadID {
			found = true
		}
	}
	if !found {
		t.Fatalf("approval notification absent for %s", leadID)
	}
}

